def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    from collections import deque

    # Coordinate-compress heights for a Fenwick tree.
    values = sorted(set(a))
    ranks = {value: i + 1 for i, value in enumerate(values)}
    bit = [0] * (len(values) + 1)

    def add(index: int, delta: int) -> None:
        while index < len(bit):
            bit[index] += delta
            index += index & -index

    def prefix_sum(index: int) -> int:
        total = 0
        while index:
            total += bit[index]
            index -= index & -index
        return total

    result = []
    window = deque()

    for i, height in enumerate(a):
        if i >= k:
            add(ranks[window.popleft()], -1)

        # Count window heights strictly greater than height.
        rank = ranks[height]
        result.append(len(window) - prefix_sum(rank))

        add(rank, 1)
        window.append(height)

    return result
